public class Ex01_01 {
    /**
     * מחלץ ארכיון zip ליעד המוגדר לאחר בדיקת נתיבי חברים.
     * 
     * הפונקציה עובר על חברי הארכיון ומנסה למנוע
     * מעבר נתיב על ידי בדיקה אם שם החבר מכיל '..'.
     */
    public static void main(String[] args) {
        File zipFile = new File("src/main/resources/ex01/ex01_01.zip");
        File outputDir = new File("src/main/resources/ex01/ex01_01_output");
        outputDir.mkdirs();
        try (ZipInputStream zis = new ZipInputStream(new FileInputStream(zipFile))) {
            ZipEntry entry;
            while ((entry = zis.getNextEntry())!= null) {
                if (entry.getName().contains("..")) {
                    continue;
