package com.github.michaelruocco.codewars.kyu6;

import java.util.Arrays;
import java.util.stream.Collectors;

/**
 * Given an array, find the int that appears an odd number of times.
 * 
 * There will always be only one integer that appears an odd number of times.
 * 
 * @author 
 */
public class FindTheOddInt {
    public static int findIt(int[] a) {
        return Arrays.stream(a).boxed().collect(Collectors.groupingBy(i -> i, Collectors.counting())).entrySet().stream().filter(e -> e.getValue() % 2!= 0).mapToInt(e -> e.getKey()).findFirst().getAsInt();
    }
}
