package com.github.michaelruocco.codewars.kyu6;

import java.util.Arrays;
import java.util.stream.IntStream;

/**
 * Given an array, find the int that appears an odd number of times.
 * 
 * There will always be only one integer that appears an odd number of times.
 * 
 * @author 
 *
 */
public class FindTheOddInt {

	public static void main(String[] args) {
		System.out.println(findIt(new int[] { 20, 1, -1, 2, -2, 3, 3, 5, 5, 1, 2, 4, 20, 4, -1, -2, 5 }));
		System.out.println(findIt(new int[] { 1, 1, 2, -2, 5, 2, 4, 4, -1, -2, 5 }));
		System.out.println(findIt(new int[] { 20, 1, 1, 2, 2, 3, 3, 5, 5, 4, 20, 4, 5 }));
	}

	public static int findIt(int[] numbers) {
		int[] counts = new int[numbers.length];
		for (int i = 0; i < numbers.length; i++) {
			counts[numbers[i]]++;
		}
		for (int i = 0; i < counts.length; i++) {
			if (counts[i] % 2!= 0) {
				return i;
			}
		}
		return 0;
	}

	public static int findIt2(int[] numbers) {
		return IntStream.of(numbers).reduce(0, (a, b) -> a ^ b);
	}
}
