package com.github.jagrosh.jok.commands.fun;

import com.github.jagrosh.jok.JokBot;
import com.github.jagrosh.jok.commands.Command;
import com.github.jagrosh.jok.utils.JokUtil;
import com.github.jagrosh.jok.utils.WebUtil;
import net.dv8tion.jda.api.EmbedBuilder;
import net.dv8tion.jda.api.entities.Message;
import net.dv8tion.jda.api.entities.MessageChannel;
import net.dv8tion.jda.api.entities.User;
import net.dv8tion.jda.api.events.message.MessageReceivedEvent;
import org.json.JSONObject;

import java.awt.*;
import java.io.IOException;
import java.util.concurrent.TimeUnit;

public class CatCommand extends Command {

    public CatCommand() {
        this.name = "cat";
        this.help = "Get a random cat image.";
        this.arguments = "";
        this.aliases = new String[]{"kitty", "kitten"};
        this.category = new Category("Fun");
    }

    @Override
    protected void execute(MessageReceivedEvent event, String[] args) {
        MessageChannel channel = event.getChannel();
        User user = event.getAuthor();
        EmbedBuilder builder = new EmbedBuilder();
        builder.setColor(Color.decode("#3498db"));
        builder.setFooter("Requested by " + user.getName(), user.getAvatarUrl());
        try {
            JSONObject json = WebUtil.getJSON("http://aws.random.cat/meow");
            String url = json.getString("file");
            builder.setTitle("Here's a cat for you!");
            builder.setImage(url);
            channel.sendMessage(builder.build()).queue();
        } catch (IOException e) {
            JokBot.log.error("Error getting cat image", e);
            channel.sendMessage("An error occurred while getting a cat image.").queue();
        }
    }
}
