package com.github.michael_collier.codewars.kyu6;

import java.util.Arrays;

/**
 * Find the unique number
 *
 * There is an array with some numbers. All numbers are equal except for one. Try to find it!
 *
 * findUniq([ 1, 1, 1, 2, 1, 1 ]) === 2
 * findUniq([ 0, 0, 0.55, 0, 0 ]) === 0.55
 * It’s guaranteed that array contains at least 3 numbers.
 *
 * https://www.codewars.com/kata/585d7d5adb20cf33cb000235/train/java
 */
public class FindTheUniqueNumber {
    public static int findUniq(int[] arr) {
        Arrays.sort(arr);
        if (arr[0]!= arr[1]) {
            return arr[0];
        } else {
            return arr[arr.length - 1];
        }
    }

    public static void main(String[] args) {
        System.out.println(findUniq(new int[]{1, 1, 1, 2, 1, 1}));
        System.out.println(findUniq(new int[]{0, 0, 0.55, 0, 0}));
    }
}
