package com.github.joshlong.codewars.kyu6;

/**
 * In this kata, your task is to find the missing number in a given integer
 * array `A`.
 * 
 * `A` can be any integer array, but all numbers will be greater than `0` and
 * each number will appear exactly once in `A`, except one which is missing.
 * 
 * @author joshlong
 *
 */
public class FindTheMissingElement {

	public static void main(String[] args) {
		System.out.println(findMissing(new int[] { 1, 2, 3, 4, 6, 7, 8 }));
		System.out.println(findMissing(new int[] { 1, 2, 3, 4, 5, 7, 8 }));
		System.out.println(findMissing(new int[] { 1, 2, 3, 4, 5, 6, 8 }));
	}

	public static int findMissing(int[] arr) {
		int result = 0;
		for (int i = 0; i < arr.length; i++) {
			if (arr[i]!= i + 1) {
				result = i + 1;
			}
		}
		return result;
	}

}
