package com.github.hcsp.io;

import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.net.URL;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

public class FileAccessor {
    /**
     * 给定一个文件名，读取这个文件，然后将其内容逐行输出。
     *
     * <p>请注意，你需要处理文件内容是 null 的情况。
     *
     * @param filename 要读取的文件名
     * @throws IOException 如果文件不存在或者其他I/O错误
     */
    public static void readLines(String filename) throws IOException {
        // 读取文件内容
        Path path = Paths.get(filename);
        List<String> lines = Files.readAllLines(path);
        // 逐行输出
        lines.forEach(System.out::println);
    }

    /**
     * 给定一个文件名，将这个文件的内容写入到另一个文件中。
     *
     * <p>请注意，你需要处理文件内容是 null 的情况。
     *
     * @param from 要读取的文件名
     * @param to 要写入的文件名
     * @throws IOException 如果文件不存在或者其他I/O错误
     */
    public static void writeToFile(String from, String to) throws IOException {
        // 读取文件内容
        Path fromPath = Paths.get(from);
        List<String> lines = Files.readAllLines(fromPath);
        // 写入文件
        Path toPath = Paths.get(to);
        Files.write(toPath, lines);
    }

    /**
     * 给定一个文件名，将这个文件的内容追加到另一个文件中。
     *
     * <p>请注意，你需要处理文件内容是 null 的情况。
     *
     * @param from 要读取的文件名
     * @param to 要写入的文件名
     * @throws IOException 如果文件不存在或者其他I/O错误
     */
    public static void appendToFile(String from, String to) throws IOException {
        // 读取文件内容
        Path fromPath = Paths.get(from);
        List<String> lines = Files.readAllLines(fromPath);
        // 写入文件
        Path toPath = Paths.get(to);
        Files.write(toPath, lines, StandardOpenOption.APPEND);
    }

    /**
     * 给定一个文件名，将这个文件的内容重命名为另一个文件名。
