import java.util.ArrayList;
import java.util.List;

public class CodeBlockWithComment {
    private List<Code> codeBlocks;
    private List<String> comments;

    public CodeBlockWithComment() {
        this.codeBlocks = new ArrayList<>();
        this.comments = new ArrayList<>();
    }

    public void addCodeBlock(Code codeBlock) {
        this.codeBlocks.add(codeBlock);
    }

    public void addComment(String comment) {
        this.comments.add(comment);
    }

    public List<Code> getCodeBlocks() {
        return codeBlocks;
    }

    public void setCodeBlocks(List<Code> codeBlocks) {
        this.codeBlocks = codeBlocks;
    }

    public List<String> getComments() {
        return comments;
    }

    public void setComments(List<String> comments) {
        this.comments = comments;
    }
}
