package com.github.shanemcd.codewars.kata.kyu6;

import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

/**
 * Find the missing element
 *
 * There is an array of non-negative integers. A second array is formed by
 * shuffling the elements of the first array and deleting a random element.
 * Given these two arrays, find which element is missing in the second array.
 *
 * @author 
 */
public class FindTheMissingElement {

    public static int findMissing(int[] array1, int[] array2) {
        List<Integer> list1 = Arrays.stream(array1).boxed().collect(Collectors.toList());
        List<Integer> list2 = Arrays.stream(array2).boxed().collect(Collectors.toList());
        return list1.stream().filter(i ->!list2.contains(i)).findFirst().get();
    }

}
