package ru.ifmo.ctddev.krylov.task1;

import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        if (args.length!= 1) {
            System.out.println("Usage: java -jar task1.jar <path>");
            return;
        }

        File file = new File(args[0]);
        if (!file.exists()) {
            System.out.println("File not found");
            return;
        }

        if (!file.isDirectory()) {
            System.out.println("Not a directory");
            return;
        }

        List<File> files = new ArrayList<>();
        try {
            files = FileUtil.getFiles(file);
        } catch (IOException e) {
            System.out.println("Error while reading files");
            return;
        }

        for (File f : files) {
            System.out.println(f.getName());
        }
    }
}
/src/main/java/ru/ifmo/ctddev/krylov/task1/FileUtil.java
package ru.ifmo.ctddev.krylov.task1;

import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class FileUtil {
    public static List<File> getFiles(File file) throws IOException {
        List<File> files = new ArrayList<>();
        if (file.isDirectory()) {
            for (File f : file.listFiles()) {
                if (f.isDirectory()) {
                    files.addAll(getFiles(f));
                } else {
                    files.add(f);
                }
            }
        } else {
            files.add(file);
        }
        return files;
    }
}
