 */
public class FindTheMissingLetter {

    public static char findMissingLetter(char[] array) {
        char[] alphabet = "abcdefghijklmnopqrstuvwxyz".toCharArray();
        for (int i = 0; i < array.length; i++) {
            if (alphabet[i]!= array[i]) {
                return alphabet[i];
            }
        }
        return'';
