package com.github.michael_b.jass.model;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;

public class JassFile {
    private String path;
    private String name;
    private String extension;
    private String content;

    public JassFile(String path) {
        this.path = path;
        this.name = path.substring(path.lastIndexOf(File.separator) + 1, path.lastIndexOf("."));
        this.extension = path.substring(path.lastIndexOf(".") + 1);
        this.content = readFile(path);
    }

    public String getPath() {
        return path;
    }

    public void setPath(String path) {
        this.path = path;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getExtension() {
        return extension;
    }

    public void setExtension(String extension) {
        this.extension = extension;
    }

    public String getContent() {
        return content;
    }

    public void setContent(String content) {
        this.content = content;
    }

    private String readFile(String path) {
        try {
            return new String(Files.readAllBytes(Paths.get(path)));
        } catch (IOException e) {
            e.printStackTrace();
        }
        return null;
    }
}
