package com.github.michael_b.jass.model;

import java.util.ArrayList;
import java.util.List;

public class JassFileParser {
    private Jass jass;
    private JassFile jassFile;

    public JassFileParser(Jass jass, JassFile jassFile) {
        this.jass = jass;
        this.jassFile = jassFile;
    }

    public void parse() {
        String[] lines = jassFile.getContent().split("\n");
        for (int i = 0; i < lines.length; i++) {
            String line = lines[i];
            if (line.contains("<|code|>")) {
                jass.getCode().add(parseCode(lines, i));
            } else if (line.contains("<|explanation|>")) {
                jass.getExplanation().add(parseExplanation(lines, i));
            } else if (line.contains("<|user|>")) {
                jass.getUser().add(parseUser(lines, i));
            } else if (line.contains("<|assistant|>")) {
                jass.getAssistant().add(parseAssistant(lines, i));
            } else if (line.contains("<|system|>")) {
                jass.getSystem().add(parseSystem(lines, i));
            }
        }
    }

    private String parseCode(String[] lines, int i) {
        StringBuilder code = new StringBuilder();
        while (!lines[i].contains("<|/code|>")) {
            code.append(lines[i]);
            i++;
        }
        return code.toString();
    }

    private String parseExplanation(String[] lines, int i) {
        StringBuilder explanation = new StringBuilder();
        while (!lines[i].contains("<|/explanation|>")) {
            explanation.append(lines[i]);
            i++;
        }
        return explanation.toString();
    }

    private String parseUser(String[] lines, int i) {
        StringBuilder user = new StringBuilder();
        while (!lines[i].contains("<|/user|>")) {
            user.append(lines[i]);
            i++;
        }
        return user.toString();
    }

    private String parseAssistant(String[] lines, int i) {
        StringBuilder assistant = new StringBuilder();
        while (!lines[i].contains("<|/assistant|>")) {
            assistant.append(lines[i]);
            i++;
        }
        return assistant.toString();
    }

    private String parseSystem(String[] lines, int i) {
        StringBuilder system = new StringBuilder();
        while (!lines[i].contains("<|/system|>")) {
            system.append(lines[i]);
            i++;
        }
        return system.toString();
    }
}
