package hu.elte.webprog.web.controller;

import hu.elte.webprog.web.model.Exercise;
import hu.elte.webprog.web.model.User;
import hu.elte.webprog.web.service.ExerciseService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestMethod;

import javax.servlet.http.HttpSession;
import java.util.List;

@Controller
public class ExerciseController {

    @Autowired
    private ExerciseService exerciseService;

    @RequestMapping(value = "/exercises", method = RequestMethod.GET)
    public String exercises(Model model, HttpSession session) {
        User user = (User) session.getAttribute("user");
        if (user == null) {
            return "redirect:/login";
        }
        List<Exercise> exercises = exerciseService.getExercises();
        model.addAttribute("exercises", exercises);
        return "exercises";
    }

    @RequestMapping(value = "/exercises/{id}", method = RequestMethod.GET)
    public String exercise(@PathVariable int id, Model model, HttpSession session) {
        User user = (User) session.getAttribute("user");
        if (user == null) {
            return "redirect:/login";
        }
        Exercise exercise = exerciseService.getExercise(id);
        model.addAttribute("exercise", exercise);
        return "exercise";
    }
}
