package hu.elte.webprog.web.model;

import java.util.List;

public class Exercise {

    private int id;
    private String name;
    private String description;
    private String code;
    private List<String> hints;

    public Exercise(int id, String name, String description, String code, List<String> hints) {
        this.id = id;
        this.name = name;
        this.description = description;
        this.code = code;
        this.hints = hints;
    }

    public int getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public String getDescription() {
        return description;
    }

    public String getCode() {
        return code;
    }

    public List<String> getHints() {
        return hints;
    }
}
