import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestMethod;

import javax.servlet.http.HttpSession;
import java.util.List;

@Controller
public class SolutionController {

    @Autowired
    private SolutionService solutionService;

    @Autowired
    private ExerciseService exerciseService;

    @RequestMapping(value = "/solutions", method = RequestMethod.GET)
    public String solutions(Model model, HttpSession session) {
        List<Solution> solutions = solutionService.getSolutions();
        model.addAttribute("solutions", solutions);
        return "solutions";
    }

    @RequestMapping(value = "/solutions/{id}", method = RequestMethod.GET)
    public String solution(@PathVariable int id, Model model, HttpSession session) {
        Solution solution = solutionService.getSolution(id);
        Exercise exercise = exerciseService.getExercise(solution.getExerciseId());
        model.addAttribute("solution", solution);
        model.addAttribute("exercise", exercise);
        return "solution";
    }
}
